-- Generated by `npm run db:schema` from a database built from supabase/migrations. Do not edit: change a migration.

create policy "upload evidence into an open dispute" on storage.objects
  as permissive
  for insert
  to authenticated
  with check (bucket_id = 'dispute-evidence'::text AND name ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[A-Za-z0-9_-]{1,80}\.[A-Za-z0-9]{1,10}$'::text AND split_part(name, '/'::text, 1) = ((( SELECT auth.uid() AS uid))::text) AND (EXISTS ( SELECT 1
   FROM public.orders o
  WHERE o.id =
        CASE
            WHEN split_part(objects.name, '/'::text, 2) ~ '^[0-9a-f-]{36}$'::text THEN split_part(objects.name, '/'::text, 2)::uuid
            ELSE NULL::uuid
        END AND o.status = 'disputed'::text AND ((( SELECT auth.uid() AS uid)) = o.buyer_id OR (( SELECT auth.uid() AS uid)) = o.seller_id) AND (( SELECT count(*) AS count
           FROM public.dispute_evidence de
          WHERE de.order_id = o.id AND de.uploader_id = (( SELECT auth.uid() AS uid)))) < 8 AND public.my_dispute_evidence_upload_count(o.id) < 16)));
